#!/usr/bin/env node
/**
 * Regenerates `src/lib/card/text/chromium-widths.json`: the widths Chromium gives a set of card
 * strings in the curated fonts, which `metrics.test.ts` holds our HarfBuzz measurement to
 * (`docs/card-system.md §4.3`; `docs/development-plan.md` Phase 4, "the Chromium reference widths
 * ... regenerated by a kept script").
 *
 * Each case is laid out as the card lays out text: one CSS pixel per card unit, `white-space: pre`,
 * `font-optical-sizing: auto`, the fonts from `public/fonts/card/` through `card-fonts.css` over
 * HTTP (as guests get them), and the width read from the span's border box, which includes the
 * trailing letter spacing Chromium adds after the last character.
 *
 * Usage: `node scripts/card/chromium-reference-widths.mjs` (Chromium from `CARD_FIXTURES_CHROMIUM`,
 * else the preinstalled `/opt/pw-browsers/chromium-1194`, else Playwright's cache). Re-run it when
 * the browser, a curated font or the cases change, and commit the JSON.
 */

import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { createServer } from "node:http";
import path from "node:path";

import { chromium } from "playwright-core";

const REPO_ROOT = path.resolve(import.meta.dirname, "../..");
const OUT = path.join(REPO_ROOT, "src/lib/card/text/chromium-widths.json");
const PREINSTALLED = "/opt/pw-browsers/chromium-1194/chrome-linux/chrome";

/** [family, weight, size, letterSpacingEm, textCase, text] */
const CASES = [
  // Display faces, as titles (no letter spacing: ligatures and contextual alternates on).
  ["Fraunces", 400, 104, 0, "none", "A Little Wild One"],
  ["Fraunces", 400, 18, 0, "none", "A Little Wild One"],
  ["Newsreader", 400, 104, 0, "none", "Welcome Little One"],
  ["Bodoni Moda", 400, 92, 0, "none", "Oh Baby, Baby"],
  ["Archivo", 400, 104, 0, "none", "AVATAR Wavy Toffee"],
  ["Playfair Display", 400, 48, 0, "none", "office affluent"],
  ["Cormorant Garamond", 400, 104, 0, "none", "The Hartwell Family"],
  ["Libre Baskerville", 400, 48, 0, "none", "Montgomery-Whitworth!"],
  // Body faces, as the invitation line (0.02em) and the uppercase details (0.06em). With letter
  // spacing Chromium turns off liga, clig, dlig, hlig and calt.
  ["Manrope", 400, 32, 0.02, "none", "Please join us for a baby shower"],
  ["Manrope", 400, 22, 0.02, "none", "Please join us as we shower Maximilian"],
  ["Manrope", 400, 18, 0.06, "uppercase", "Hosted by Wilhelmina Montgomery"],
  ["Manrope", 400, 24, 0.06, "uppercase", "10:30 pm – 11:30 pm"],
  // Manrope's contextual alternates change the advances of these with `calt` on.
  ["Manrope", 400, 18, 0.06, "uppercase", "12:30 pm - 4:45 pm (MDT)"],
  ["Manrope", 400, 18, 0.06, "uppercase", "Montgomery-Whitworth Manor"],
  ["Manrope", 400, 24, 0.06, "uppercase", "Wednesday, September 30, 2026 (Midweek!)"],
  ["Inter", 400, 24, 0.06, "uppercase", "Saturday, September 12, 2026"],
  ["Inter", 400, 18, 0.06, "uppercase", "Wednesday, September 30"],
  ["Inter Tight", 400, 18, 0.06, "uppercase", "RSVP by September 30"],
  ["DM Sans", 400, 18, 0.06, "uppercase", "The Grand Ballroom at Montgomery"],
  ["Karla", 400, 18, 0.06, "uppercase", "Maximilian Augustin"],
  ["Work Sans", 400, 18, 0.06, "uppercase", "Hosted by Maya & Tom"],
  ["Figtree", 400, 18, 0.06, "uppercase", "12:30 pm – 4:45 pm"],
  ["Source Sans 3", 400, 18, 0.06, "uppercase", "Kindly RSVP by Wednesday"],
];

function chromiumExecutable() {
  if (process.env.CARD_FIXTURES_CHROMIUM) return process.env.CARD_FIXTURES_CHROMIUM;
  return existsSync(PREINSTALLED) ? PREINSTALLED : undefined;
}

function startServer(page) {
  const server = createServer((req, res) => {
    void (async () => {
      const pathname = new URL(req.url ?? "/", "http://ref").pathname;
      try {
        if (pathname === "/") {
          res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
          res.end(page);
          return;
        }
        if (pathname === "/card-fonts.css") {
          res.writeHead(200, { "content-type": "text/css; charset=utf-8" });
          res.end(await readFile(path.join(REPO_ROOT, "src/styles/card-fonts.css")));
          return;
        }
        const font = /^\/fonts\/card\/([A-Za-z0-9]+-normal-\d+\.woff2)$/.exec(pathname);
        if (font) {
          res.writeHead(200, { "content-type": "font/woff2" });
          res.end(await readFile(path.join(REPO_ROOT, "public/fonts/card", font[1])));
          return;
        }
        res.writeHead(404).end();
      } catch {
        res.writeHead(404).end();
      }
    })();
  });
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(server)));
}

const escapeHtml = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const spans = CASES.map(
  ([family, weight, size, ls, textCase, text], i) =>
    `<div><span data-case="${i}" style="font-family:'${family}';font-weight:${weight};` +
    `font-size:${size}px;letter-spacing:${ls}em;text-transform:${textCase}">${escapeHtml(text)}</span></div>`,
).join("");
const html =
  `<!doctype html><html lang="en"><head><meta charset="utf-8">` +
  `<link rel="stylesheet" href="/card-fonts.css">` +
  `<style>body{margin:0}div{white-space:pre;line-height:1}span{font-optical-sizing:auto;font-style:normal}</style>` +
  `</head><body>${spans}</body></html>`;

const server = await startServer(html);
const browser = await chromium.launch({
  executablePath: chromiumExecutable(),
  headless: true,
  args: ["--no-sandbox", "--disable-dev-shm-usage"],
});
try {
  const context = await browser.newContext({
    viewport: { width: 2000, height: 1000 },
    deviceScaleFactor: 1,
  });
  const page = await context.newPage();
  await page.goto(`http://127.0.0.1:${server.address().port}/`, { waitUntil: "load" });
  const result = await page.evaluate(async (cases) => {
    document.body.getBoundingClientRect();
    await document.fonts.ready;
    const unloaded = cases
      .filter(([family, weight]) => !document.fonts.check(`${weight} 16px "${family}"`))
      .map(([family, weight]) => `${family} ${weight}`);
    const widths = [...document.querySelectorAll("[data-case]")].map(
      (el) => Math.round(el.getBoundingClientRect().width * 1000) / 1000,
    );
    return { unloaded, widths };
  }, CASES);
  if (result.unloaded.length > 0)
    throw new Error(`fonts not loaded: ${result.unloaded.join(", ")}`);
  const cases = CASES.map(([family, weight, size, letterSpacingEm, textCase, text], i) => ({
    family,
    weight,
    size,
    letterSpacingEm,
    textCase,
    text,
    width: result.widths[i],
  }));
  const out = { chromium: browser.version(), cases };
  await writeFile(OUT, `${JSON.stringify(out, null, 2)}\n`);
  console.log(
    `Chromium ${browser.version()}: ${cases.length} widths → ${path.relative(REPO_ROOT, OUT)}`,
  );
} finally {
  await browser.close();
  server.close();
}
